        "answer": "संयुक्त राष्ट्र संघ का आलोचनात्मक मूल्यांकन करें ।\nउत्तर:\n24 अक्टूबर 1945 को स्थापित संयुक्त राष्ट्र संघ (UNO) विश्व में शांति, सुरक्षा और सहयोग का सबसे बड़ा अंतरराष्ट्रीय मंच है। \n\nप्रमुख सफलताएँ एवं उपलब्धियाँ:\n1. तीसरे विश्व युद्ध को रोकना: शीतयुद्ध और उसके बाद के दौर में यूएनओ ने महाशक्तियों के परमाणु तनाव को सीमित रखा और तृतीय विश्व युद्ध की विभीषिका को टालने में सफल रहा।\n2. शांति स्थापना अभियान: यूएन शांति सेनाओं ने कांगो, साइप्रस, लेबनान और कंबोडिया जैसे कई युद्धग्रस्त क्षेत्रों में शांति बहाल की।\n3. सामाजिक व मानवीय विकास: यूनिसेफ, डब्ल्यूएचओ और यूनेस्को के माध्यम से विश्व से चेचक और पोलियो का उन्मूलन, बाल अधिकारों की रक्षा और शरणार्थियों को मानवीय सहायता प्रदान की।\n\nकमजोरियाँ एवं आलोचनाएँ:\n1. सुरक्षा परिषद में P-5 का वीटो एकाधिकार: 5 स्थायी सदस्य अपने संकीर्ण हितों की रक्षा के लिए वीटो का दुरुपयोग करते हैं, जिससे कई बड़े मानवीय संकटों (जैसे सीरिया, यूक्रेन-रूस युद्ध, गाजा संकट) में यूएन असहाय साबित हुआ।\n2. लोकतांत्रिक प्रतिनिधित्व का अभाव: वर्तमान सुरक्षा परिषद 1945 की शक्ति संरचना को दर्शाती है। भारत, ब्राजील, जापान और अफ्रीकी देशों को स्थायी प्रतिनिधित्व न मिलना इसकी विश्वसनीयता पर प्रश्नचिह्न लगाता है।\n3. वित्तीय निर्भरता: अमेरिका जैसे बड़े देशों पर वित्तीय निर्भरता के कारण यह कई बार अमेरिकी विदेश नीति के प्रभाव में कार्य करता नजर आता है।\n\nनिष्कर्ष:\nतमाम सीमाओं के बावजूद, डैग हैमरशोल्ड के शब्दों में—\"संयुक्त राष्ट्र संघ का निर्माण मानवता को स्वर्ग ले जाने के लिए नहीं, बल्कि नरक से बचाने के लिए हुआ था।\" यह आज भी वैश्विक संवाद की एकमात्र अपरिहार्य संस्था है।\n\n---"
